/* Curated two-wheeler service catalog: common and legacy model families. */
const twoWheelerCatalog={Hero:['Splendor Plus','Splendor Plus XTEC','HF Deluxe','HF 100','Passion Pro','Passion Plus','Glamour','Super Splendor','Xtreme 125R','Xtreme 160R','XPulse 200 4V','Karizma XMR'],Honda:['Activa','Activa 6G','Activa 125','Dio','Shine','SP 125','Unicorn','Hornet 2.0','Hness CB350'],Bajaj:['Pulsar 150','Pulsar NS160','Pulsar NS200','Pulsar N160','Pulsar N250','Platina 100','CT 110X','Avenger Street 160','Dominar 400','Chetak'],TVS:['Apache RTR 160','Apache RTR 160 4V','Apache RTR 200 4V','Raider 125','Jupiter','Jupiter 125','Ntorq 125','XL100','Ronin','Radeon','iQube'],Yamaha:['FZ','FZ-S','R15','MT-15','Fascino 125','RayZR 125'],Suzuki:['Access 125','Burgman Street','Gixxer','Gixxer SF','V-Strom SX'],'Royal Enfield':['Classic 350','Bullet 350','Hunter 350','Meteor 350','Himalayan 450','Interceptor 650','Continental GT 650'],KTM:['200 Duke','250 Duke','390 Duke','Duke 200','Duke 390','RC 200','RC 390','390 Adventure'],Jawa:['42','Perak','350'],Yezdi:['Roadster','Scrambler','Adventure'],Ather:['450S','450X','450 Apex','Rizta'],'Ola Electric':['S1 Pro','S1 Air','S1 X']};
function nonTwoWheelerMake(make){return ['hyundai','maruti','maruti suzuki','tata','mahindra','toyota','kia','renault','nissan','skoda','volkswagen','ford','chevrolet','mg','mg motor','isuzu','ashok leyland','eicher','force','mercedes','mercedes-benz','audi','jeep'].includes(String(make||'').trim().toLowerCase())}
function migrateTwoWheelerCatalog(){if(db.twoWheelerCatalogVersion===1)return true;let before=structuredClone(db);try{db.legacyVehicleDropdowns=db.legacyVehicleDropdowns||{makes:structuredClone(db.lists['Vehicle Brands']||[]),models:structuredClone(db.vehicleModels||[]),types:structuredClone(db.lists['Vehicle Types']||[])};db.lists['Vehicle Brands']=(db.lists['Vehicle Brands']||[]).filter(make=>!nonTwoWheelerMake(make));db.vehicleModels=(db.vehicleModels||[]).filter(entry=>!nonTwoWheelerMake(entry.make));for(let [make,models]of Object.entries(twoWheelerCatalog))for(let model of models)addSharedVehicleOption(make,model);let types=['Bike','Scooter','Moped','Electric Bike','Electric Scooter'];for(let type of db.lists['Vehicle Types']||[])if(!/car|suv|truck|bus|tractor|pickup|rickshaw|4.?wheel|commercial/i.test(type)&&!types.some(v=>v.toLowerCase()===type.toLowerCase()))types.push(type);db.lists['Vehicle Types']=types;db.twoWheelerCatalogVersion=1;db.lists['Vehicle Models']=db.vehicleModels.map(v=>v.make+' — '+v.model);if(save()===false){db=before;return false}return true}catch(error){db=before;toast('Could not update two-wheeler lists: '+error.message);return false}}
const addVehicleOptionBeforeTwoWheelers=addSharedVehicleOption;
addSharedVehicleOption=function(make,model){if(nonTwoWheelerMake(make))return;return addVehicleOptionBeforeTwoWheelers(make,model)};
partVehicleMakes=function(){return (db.lists['Vehicle Brands']||[]).filter(make=>!nonTwoWheelerMake(make)).slice().sort((a,b)=>a.localeCompare(b))};
const modelOptionsBeforeTwoWheelers=partVehicleModels;
partVehicleModels=function(make){return nonTwoWheelerMake(make)?[]:modelOptionsBeforeTwoWheelers(make)};
const vehicleMakeField=schemas.bikes.find(f=>f.key==='brand');vehicleMakeField.label='Vehicle Make (Two-Wheeler)';vehicleMakeField.options=()=>partVehicleMakes();
const fieldBeforeTwoWheelerLegacy=field;
field=function(f,record={}){if(f.type==='select'&&(['brand','type'].includes(f.key))&&schemas.bikes.includes(f)&&record[f.key]){let options=typeof f.options==='function'?f.options():f.options||[];if(!options.some(option=>String(typeof option==='object'?option.value:option)===String(record[f.key])))f={...f,options:[...options,{value:record[f.key],label:record[f.key]+' (existing record)'}]}}return fieldBeforeTwoWheelerLegacy(f,record)};
const restoreBeforeTwoWheelerCatalog=validateBackup;
validateBackup=function(text){let data=restoreBeforeTwoWheelerCatalog(text);if(data.legacyVehicleDropdowns!==undefined&&(!data.legacyVehicleDropdowns||!Array.isArray(data.legacyVehicleDropdowns.makes)||!Array.isArray(data.legacyVehicleDropdowns.models)||!Array.isArray(data.legacyVehicleDropdowns.types)))throw Error('Invalid archived vehicle dropdowns.');return data};
migrateTwoWheelerCatalog();render();
